<?php $title='Calendário';require __DIR__.'/_top.php';$exportUrl=flash('calendar_export_url');$prev=$start->modify('-1 month')->format('Y-m');$next=$start->modify('+1 month')->format('Y-m');?>
<div class="page-heading"><div><p class="eyebrow">Ocupação unificada</p><h1>Calendário</h1></div><div class="month-nav"><a href="?mes=<?= e($prev) ?>">←</a><strong><?= e($start->format('m/Y')) ?></strong><a href="?mes=<?= e($next) ?>">→</a></div></div>
<section class="admin-panel calendar-panel"><div class="calendar-weekdays"><?php foreach(['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'] as $dayName):?><span><?= e($dayName) ?></span><?php endforeach;?></div><div class="month-grid"><?php $cursor=$start->modify('-'.$start->format('w').' days');for($cell=0;$cell<42;$cell++,$cursor=$cursor->modify('+1 day')):$day=$cursor->format('Y-m-d');?><article class="calendar-day <?= $cursor->format('m')!==$start->format('m')?'outside':'' ?>"><strong><?= $cursor->format('d') ?></strong><?php foreach($unifiedEvents as $event):$eventStart=substr((string)$event['starts_at'],0,10);$eventEnd=substr((string)$event['ends_at'],0,10);if($eventStart<=$day&&$eventEnd>$day):?><?php if($event['type']==='reservation'):?><a class="calendar-event status-<?= e(strtolower($event['status'])) ?>" href="<?= e(base_url('admin/reservas/'.$event['id'])) ?>"><?= e($event['title']) ?><small><?= e($event['source']) ?></small></a><?php else:?><span class="calendar-event <?= e($event['type']) ?>" title="<?= e($event['title']) ?>"><?= e($event['type']) ?><small><?= e($event['title']) ?> · <?= e($event['source']) ?></small></span><?php endif;?><?php endif;endforeach;?></article><?php endfor;?></div></section>
<div class="detail-grid"><section class="admin-panel"><h2>Novo bloqueio</h2><form class="admin-form" action="<?= e(base_url('admin/bloqueios')) ?>" method="post"><?= csrf_field() ?><label>Início<input type="date" name="data_inicio" required></label><label>Fim (data liberada)<input type="date" name="data_fim" required></label><label>Tipo<select name="origem"><option value="USO_PROPRIO">Uso próprio</option><option value="MANUTENCAO">Manutenção</option><option value="RESERVA_EXTERNA">Reserva externa</option><option value="INDISPONIBILIDADE">Indisponibilidade</option><option value="OUTRO">Outro</option></select></label><label>Motivo<input name="motivo" maxlength="255" required></label><button class="admin-primary">Bloquear datas</button></form><?php foreach($blocks as $block):?><div class="block-row"><div><strong><?= e($block['motivo']) ?></strong><small><?= e($block['data_inicio']) ?>–<?= e($block['data_fim']) ?> · <?= e($block['origem']) ?></small></div><?php if(!$block['reserva_id']):?><form action="<?= e(base_url('admin/bloqueios/'.$block['id'].'/excluir')) ?>" method="post" data-confirm="Excluir este bloqueio?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$block['id'] ?>"><button class="admin-danger">Excluir</button></form><?php endif;?></div><?php endforeach;?></section>
<section class="admin-panel"><h2>Fontes iCal</h2><form class="admin-form" action="<?= e(base_url('admin/operacoes/calendar-source-create')) ?>" method="post"><?= csrf_field() ?><label>Nome<input name="name" required></label><label>Provedor<select name="provider"><option>AIRBNB</option><option>BOOKING</option><option>GOOGLE</option><option value="OTHER">Outro</option></select></label><label>URL do feed<input type="url" name="feed_url" required><small>Use o link de exportação iCal fornecido pela plataforma, normalmente terminado em .ics.</small></label><label>Timezone<input name="timezone" value="America/Sao_Paulo" required></label><label>Intervalo (minutos)<input type="number" name="interval" min="5" max="1440" value="30"></label><button class="admin-primary">Adicionar fonte</button></form><?php foreach($calendarSources as $source):?><div class="block-row"><div><strong><?= e($source['nome']) ?> · <?= e($source['provider']) ?></strong><small><?= e($source['ultimo_status']??'Ainda não sincronizado') ?> · última <?= e($source['ultimo_sync_em']??'nunca') ?> · próxima <?= e($source['proximo_sync_em']??'agora') ?></small><?php if($source['ultimo_erro']):?><small class="message-error"><?= e($source['ultimo_erro']) ?></small><?php endif;?></div><form method="post" action="<?= e(base_url('admin/operacoes/calendar-source-sync')) ?>"><?= csrf_field() ?><input type="hidden" name="source_id" value="<?= (int)$source['id'] ?>"><button class="admin-secondary">Sincronizar agora</button></form></div><?php endforeach;?></section></div>
<div class="detail-grid"><section class="admin-panel"><h2>Exportação iCal privada</h2><p>O feed expõe apenas ocupação, sem dados do hóspede ou valores.</p><form class="admin-form" method="post" action="<?= e(base_url('admin/operacoes/calendar-export-create')) ?>"><?= csrf_field() ?><label>Nome<input name="name" value="Feed principal"></label><button class="admin-primary">Gerar link revogável</button></form>
<?php if($exportUrl):?><div class="export-link-card" role="status"><strong>Link criado. Copie agora.</strong><p>Por segurança, este endereço completo não será exibido novamente.</p><div class="copy-link-row"><input id="calendar-export-url" type="text" readonly value="<?= e($exportUrl) ?>" aria-label="Link privado do calendário"><button class="admin-secondary" type="button" data-copy-target="calendar-export-url" data-copy-feedback="calendar-export-copy-feedback">Copiar link</button></div><small id="calendar-export-copy-feedback" class="copy-feedback" aria-live="polite"></small></div><?php endif;?>
<?php if(!$exportTokens):?><p class="empty-state">Nenhum link de exportação criado.</p><?php endif;?><?php foreach($exportTokens as $export):?><div class="block-row"><div><strong><?= e($export['nome']) ?></strong><small>Criado em <?= e($export['created_at']) ?><?= $export['last_used_at']?' · último acesso '.e($export['last_used_at']):' · ainda não acessado' ?><?= $export['revoked_at']?' · revogado em '.e($export['revoked_at']):'' ?></small></div><?php if((int)$export['ativo']===1&&!$export['revoked_at']):?><form method="post" action="<?= e(base_url('admin/operacoes/calendar-export-revoke')) ?>" data-confirm="Revogar este link iCal? A sincronização que o utiliza deixará de funcionar."><?= csrf_field() ?><input type="hidden" name="export_id" value="<?= (int)$export['id'] ?>"><button class="admin-danger">Revogar</button></form><?php else:?><span class="admin-status">Revogado</span><?php endif;?></div><?php endforeach;?></section><section class="admin-panel"><h2>Sincronizações</h2><?php if(!$syncLogs):?><p class="empty-state">Nenhuma sincronização.</p><?php endif;?><?php foreach($syncLogs as $log):?><div class="block-row"><strong><?= e($log['source_name']) ?> · <?= e($log['status']) ?></strong><small>lidos <?= (int)$log['events_seen'] ?> · novos <?= (int)$log['events_created'] ?> · atualizados <?= (int)$log['events_updated'] ?> · <?= e($log['created_at']) ?><?= $log['error_message']?' · '.e($log['error_message']):'' ?></small></div><?php endforeach;?></section></div>
<?php require __DIR__.'/_bottom.php';?>
